  const card=document.querySelector('.tool-grid>div:nth-child(2) .tool-status');if(card)card.textContent=connection.connected?'Google connected':'Not connected';const count=document.querySelector('.stats .stat:nth-child(4) strong');if(count)count.replaceChildren(document.createTextNode(connection.connected?'1 ':'0 '),node('small','/ 4'));
