$('#gbp-export').addEventListener('click',()=>{const exported=JSON.parse(JSON.stringify(state));exported.queue.forEach(x=>{delete x.previewId;delete x.previewExpires;if(x.status==='validated')x.status='draft';});const blob=new Blob([JSON.stringify({app:'SEO Ghost GBP',version:1,workspace:exported},null,2)],{type:'application/json'});const a=node('a');a.href=URL.createObjectURL(blob);a.download='seo-ghost-gbp-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});
$('#gbp-import').addEventListener('click',()=>$('#gbp-import-file').click());
$('#gbp-import-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw new Error('Backup is too large.');const data=JSON.parse(await file.text());if(data.app!=='SEO Ghost GBP'||data.version!==1||!data.workspace||!Array.isArray(data.workspace.queue)||!Array.isArray(data.workspace.history))throw new Error('Choose a valid SEO Ghost GBP backup.');
  const w=data.workspace;if(w.snapshot&&(!['manual','google'].includes(w.snapshot.source)||typeof w.snapshot.name!=='string'||!Number.isFinite(Date.parse(w.snapshot.capturedAt))))throw new Error('Invalid listing capture.');if(!Array.isArray(w.reviews)||!w.content||typeof w.content!=='object'||w.queue.some(x=>!x||!['location','reply'].includes(x.kind)||!x.changes||!x.before||typeof x.createdAt!=='string')||w.history.some(x=>typeof x.message!=='string'))throw new Error('Invalid workspace records.');
  if(!confirm('Replace the current GBP workspace with this backup? Your business profile and Google credentials are unchanged.'))return;
  // Imported captures are evidence supplied by a file, never trusted as a live Google snapshot.
  w.aiResult=null;w.aiFingerprint=null;w.actionsTaken={};
  w.observations=Array.isArray(w.observations)?w.observations.map(x=>{const row=GhostOptimization.observation(x);if(row.date>today())throw new Error('Imported measurements cannot have future dates.');return {...row,id:crypto.randomUUID(),createdAt:x.createdAt||stamp()};}):[];
  w.competitors=Array.isArray(w.competitors)?w.competitors:[];if(w.competitors.some(x=>!x||typeof x.name!=='string'||typeof x.query!=='string'||typeof x.point!=='string'||typeof x.date!=='string'||!Number.isInteger(x.reviews)||x.reviews<0||!Number.isFinite(x.rating)||x.rating<1||x.rating>5))throw new Error('Invalid competitor observations.');
  if(w.snapshot){w.snapshot.source='manual';w.snapshot.raw=null;w.snapshot.accountName='';}
  w.queue.forEach(x=>{x.source='manual';delete x.previewId;delete x.previewExpires;if(x.status==='validated')x.status='draft';});w.reviews.forEach(x=>x.source='manual');state={version:1,...w};save();fillSnapshot();renderAll();notify('Workspace imported as manual data. Recapture Google before live editing.');
}catch(err){notify(err instanceof SyntaxError?'Invalid JSON backup.':err.message);}finally{e.target.value='';}});
